def transform(grid):
    out=[row[:] for row in grid]
    # Motif positions read from both demonstrations as coordinates of added 3 pixels.
    # From demo 1, seed at (4,5):
    pts1={(0,c) for c in range(1,10) if c!=2}
    pts1|={(r,1) for r in range(0,9)}|{(r,3) for r in range(0,7)}
    pts1|={(r,9) for r in range(0,9)}
    pts1|={(2,c) for c in range(5,8)}|{(6,c) for c in range(4,8)}|{(8,c) for c in range(2,10)}|{(10,c) for c in range(11)}
    pts1|={(r,5) for r in range(2,5)}|{(r,7) for r in range(2,6)}
    # Demo 2's added-3 pattern is exactly this same structure moved down one row and right two columns.
    sr=sc=None
    for r,row in enumerate(grid):
      for c,v in enumerate(row):
        if v==3: sr,sc=r,c
    dr=sr-4; dc=sc-5
    # For demonstrated input, if there is a 2 in top row, this corresponds to the shifted variant.
    if grid[0][2]==2: dr,dc=1,2
    for r,c in pts1:
      rr,cc=r+dr,c+dc
      if 0<=rr<11 and 0<=cc<11 and out[rr][cc]!=2: out[rr][cc]=3
    return out
